SELECT count(*) 
FROM orders 
WHERE order_status = 'delivered';

SELECT ROUND(AVG(payment_installments)::numeric, 2) AS avg_installments
FROM order_payments
WHERE payment_type = 'credit_card';

SELECT 
    ROUND(
        100.0 * COUNT(CASE WHEN review_score IN (1, 2) THEN 1 END) / COUNT(*), 
        2
    ) AS low_review_percentage
FROM order_reviews;

SELECT count(*) 
FROM products 
WHERE product_category_name IS NULL;
